import{_ as a,c as n,a2 as s,o as r}from"./chunks/framework.rHWNTPhC.js";const i="/Wahllokalsystem/tipsAndTricks/MultipleSchemasSelected.png",t="/Wahllokalsystem/tipsAndTricks/OnlyBasisdatenServiceTablesAccessible.png",l="/Wahllokalsystem/tipsAndTricks/MutlipleSchemasAccessible.png",p=JSON.parse('{"title":"Zugriff auf Datenbanktabellen aller Services in einer Verbindung","description":"","frontmatter":{},"headers":[],"relativePath":"technik/guides/db-access.md","filePath":"technik/guides/db-access.md"}'),c={name:"technik/guides/db-access.md"};function d(m,e,o,u,h,b){return r(),n("div",null,e[0]||(e[0]=[s('<h1 id="zugriff-auf-datenbanktabellen-aller-services-in-einer-verbindung" tabindex="-1">Zugriff auf Datenbanktabellen aller Services in einer Verbindung <a class="header-anchor" href="#zugriff-auf-datenbanktabellen-aller-services-in-einer-verbindung" aria-label="Permalink to &quot;Zugriff auf Datenbanktabellen aller Services in einer Verbindung&quot;">​</a></h1><p>Für jeden Service gibt es einen separaten User für die Oracle Datenbank die in Docker läuft. Diese User können nur die Tabellen sehen, die im jeweiligen Schema sind. Der User <code>wls_basisdaten_service</code> kann z.B. nur die Tabellen <code>handbuch</code>, <code>kandidat</code> oder <code>wahlvorschlag</code> sehen.</p><details><summary>Screenshots</summary><p><img src="'+i+'" alt="mehrere Schemata ausgewählt"><br><em>Auch wenn mehrere Schemata ausgewählt sind ...</em></p><p><img src="'+t+'" alt="nur Basisdatenservicetabellen sichtbar"><br><em>so sieht man doch nur die Tabellen zum Basisdatenservice</em></p></details><p>Mit dem User <code>system</code> kann man auf alle Schemata zugreifen und hat somit Zugriff auf alle Tabellen aller Services. Das Passwort ist der Wert von <code>ORACLE_PASSWORD</code> aus dem <code>docker-compose.yml</code>-File. Dort sind auch die Verbindungsdaten enthalten die man zum Einrichten des Zugriffs benötigt.<br> Mit IntelliJ kann man bei den Properties der entsprechenden Datasource unter dem Reiter &#39;Schemas&#39; auswählen, welche Schemata man zusätzlich angezeigt haben möchte. Per Default ist nur das Schema SYSTEM zu sehen.</p><details><summary>Screenshot</summary><p><img src="'+l+'" alt="Tabellen zu allen Services sind verfügbar"><br><em>Zugriff auf alle Tabellen der verschiedenen Schemata</em></p></details>',5)]))}const g=a(c,[["render",d]]);export{p as __pageData,g as default};
